      lang_choose_h: 'மொழி', lang_cur: 'பயன்பாட்டில்', lang_st_full: 'எல்லாப் பக்கங்களும்',
      lang_st_part_hi: 'முக்கியப் பக்கங்களும் பாதுகாப்பு வழிகாட்டியும். மீதி இப்போதைக்கு இந்தியில்.', lang_st_part_en: 'முக்கியப் பக்கங்களும் பாதுகாப்பு வழிகாட்டியும். மீதி இப்போதைக்கு ஆங்கிலத்தில்.',
      lang_review_h: 'சில பக்கங்கள் ஏன் இன்னும் இந்தி அல்லது ஆங்கிலத்தில் உள்ளன',
      lang_review_p: 'உடல்நலச் சொல் ஒவ்வொன்றும் எல்லா மொழியிலும் ஒரே பொருளைத் தர வேண்டும். அதனால் அந்த மொழி பேசும் டாக்டர்கள் மொழிபெயர்ப்பை வெளியிடும் முன் சரிபார்க்கிறார்கள். அதுவரை “இன்று”, டைரி, பதிவு செய்தல், பாதுகாப்பு வழிகாட்டி ஆகியவை மொழிபெயர்க்கப்பட்டுள்ளன; வழிகாட்டிகளும் கருவிகளும் இந்தியில் (மராத்திக்கு) அல்லது ஆங்கிலத்தில் தெரியும்.',
      lang_review_p2: 'ஏதாவது வாக்கியம் விசித்திரமாகத் தோன்றினால், இந்தி அல்லது ஆங்கில வடிவத்தையே நம்புங்கள். உதவி எண்கள் எல்லா மொழியிலும் ஒன்றே.',
      lang_n_en: 'ஆங்கிலம்', lang_n_hi: 'இந்தி', lang_n_mr: 'மராத்தி', lang_n_bn: 'வங்காளம்', lang_n_ta: 'தமிழ்', lang_n_te: 'தெலுங்கு',
      lang_read_h: 'உரக்கப் படித்தல்', lang_read_p: 'எந்தப் பக்கத்திலும் மேலே உள்ள ஸ்பீக்கரைத் தட்டினால் அந்தப் பக்கத்தைக் கேட்கலாம். நிறுத்த மீண்டும் தட்டுங்கள். வேறு பக்கத்தைத் திறந்தாலும் படிப்பது நின்றுவிடும்.',
      lang_speed: 'வேகம்', lang_slow: 'மெதுவாக', lang_normal: 'வழக்கமான', lang_test: 'கேட்டுப் பாருங்கள்', lang_stop: 'படிப்பதை நிறுத்து', lang_read_btn: 'இந்தப் பக்கத்தைப் படித்துக் காட்டு',
      lang_test_say: 'தமிழில் உரக்கப் படிப்பது இப்படித்தான் கேட்கும். எந்தப் பக்கத்திலும் மேலே உள்ள ஸ்பீக்கரைத் தட்டினால் அந்தப் பக்கத்தைக் கேட்கலாம்.',
      lang_voice_checking: 'இந்த ஃபோனில் குரலைத் தேடுகிறோம்…', lang_voice_ok: 'குரல்: {name}', lang_voice_local: 'ஃபோனிலேயே இயங்கும்', lang_voice_online: 'பிரவுசரின் ஆன்லைன் குரல்',
      lang_voice_fb: 'இந்த ஃபோனில் {lang} குரல் இல்லை. அதற்குப் பதில் {fb} குரல் படிக்கும்: {name}', lang_voice_none: 'இந்த ஃபோனில் இன்னும் {lang} குரல் இல்லை. கீழே உள்ள படிகளில் சேர்க்கலாம்.',
